#!/usr/bin/env python3
import sys, threading

class PErr(Exception): pass
class TErr(Exception): pass
class RErr(Exception): pass

KW = {'let', 'rec', 'in', 'if', 'then', 'else', 'match', 'with', 'type', 'forall'}

def lex(s):
    toks = []
    i = 0; n = len(s)
    while i < n:
        c = s[i]
        if c in ' \t\n\r\f\v':
            i += 1; continue
        if c == '-' and i + 1 < n and s[i+1] == '-':
            while i < n and s[i] != '\n': i += 1
            continue
        if c.isdigit() and c.isascii():
            j = i
            while j < n and s[j] in '0123456789': j += 1
            toks.append(('INT', int(s[i:j]))); i = j; continue
        if ('a' <= c <= 'z') or c == '_' or ('A' <= c <= 'Z'):
            j = i + 1
            while j < n and (s[j].isascii() and (s[j].isalnum() or s[j] == '_')): j += 1
            w = s[i:j]; i = j
            if 'A' <= c <= 'Z':
                if w in ('True', 'False', 'Int', 'Bool'): toks.append((w, None))
                else: raise PErr()
            elif w == '_': raise PErr()
            elif w in KW:
                if w in ('match', 'with', 'type', 'forall'): raise PErr()
                toks.append((w, None))
            else: toks.append(('ID', w))
            continue
        two = s[i:i+2]
        if two in ('//', '->', '=='):
            toks.append((two, None)); i += 2; continue
        if c in '()/+-*%<=:':
            toks.append((c, None)); i += 1; continue
        raise PErr()
    toks.append(('EOF', None))
    return toks

class Parser:
    def __init__(self, toks): self.t = toks; self.p = 0
    def peek(self): return self.t[self.p][0]
    def next(self):
        t = self.t[self.p]; self.p += 1; return t
    def expect(self, k):
        t = self.next()
        if t[0] != k: raise PErr()
        return t
    def program(self):
        e = self.expr(); self.expect('EOF'); return e
    def expr(self):
        k = self.peek()
        if k == '/':
            self.next(); x = self.expect('ID')[1]; self.expect('->')
            return ('lam', x, self.expr())
        if k == 'let':
            self.next()
            if self.peek() == 'rec':
                self.next(); f = self.expect('ID')[1]; self.expect(':'); T = self.type()
                self.expect('='); e1 = self.expr()
                if e1[0] != 'lam': raise PErr()
                self.expect('in'); e2 = self.expr()
                return ('letrec', f, T, e1, e2)
            x = self.expect('ID')[1]; T = None
            if self.peek() == ':':
                self.next(); T = self.type()
            self.expect('='); e1 = self.expr(); self.expect('in'); e2 = self.expr()
            return ('let', x, T, e1, e2)
        if k == 'if':
            self.next(); c = self.expr(); self.expect('then'); a = self.expr()
            self.expect('else'); b = self.expr()
            return ('if', c, a, b)
        a = self.add()
        if self.peek() in ('==', '<'):
            op = self.next()[0]; b = self.add()
            return ('bin', op, a, b)
        return a
    def add(self):
        a = self.mul()
        while self.peek() in ('+', '-'):
            op = self.next()[0]; a = ('bin', op, a, self.mul())
        return a
    def mul(self):
        a = self.app()
        while self.peek() in ('*', '//', '%'):
            op = self.next()[0]; a = ('bin', op, a, self.app())
        return a
    ATOM = ('ID', 'INT', 'True', 'False', '(')
    def app(self):
        a = self.atom()
        while self.peek() in self.ATOM:
            a = ('app', a, self.atom())
        return a
    def atom(self):
        t = self.next(); k = t[0]
        if k == 'ID': return ('var', t[1])
        if k == 'INT': return ('int', t[1])
        if k == 'True': return ('bool', True)
        if k == 'False': return ('bool', False)
        if k == '(':
            e = self.expr()
            if self.peek() == ':':
                self.next(); T = self.type(); self.expect(')')
                return ('anno', e, T)
            self.expect(')'); return e
        raise PErr()
    def type(self):
        a = self.tatom()
        if self.peek() == '->':
            self.next(); return ('fn', a, self.type())
        return a
    def tatom(self):
        t = self.next()[0]
        if t == 'Int' or t == 'Bool': return t
        if t == '(':
            T = self.type(); self.expect(')'); return T
        raise PErr()

class TV:
    __slots__ = ('ref',)
    def __init__(self): self.ref = None

def prune(t):
    while isinstance(t, TV) and t.ref is not None: t = t.ref
    return t

def occurs(v, t):
    t = prune(t)
    if t is v: return True
    if isinstance(t, tuple): return occurs(v, t[1]) or occurs(v, t[2])
    return False

def unify(a, b):
    a = prune(a); b = prune(b)
    if a is b: return
    if isinstance(a, TV):
        if occurs(a, b): raise TErr()
        a.ref = b; return
    if isinstance(b, TV): unify(b, a); return
    if isinstance(a, str) or isinstance(b, str):
        if a != b: raise TErr()
        return
    unify(a[1], b[1]); unify(a[2], b[2])

def infer(env, e):
    k = e[0]
    if k == 'int': return 'Int'
    if k == 'bool': return 'Bool'
    if k == 'var':
        x = e[1]
        while env is not None:
            if env[0] == x: return env[1]
            env = env[2]
        raise TErr()
    if k == 'lam':
        a = TV()
        r = infer((e[1], a, env), e[2])
        return ('fn', a, r)
    if k == 'app':
        f = infer(env, e[1]); x = infer(env, e[2]); r = TV()
        unify(f, ('fn', x, r)); return r
    if k == 'bin':
        unify(infer(env, e[2]), 'Int'); unify(infer(env, e[3]), 'Int')
        return 'Bool' if e[1] in ('==', '<') else 'Int'
    if k == 'if':
        unify(infer(env, e[1]), 'Bool')
        a = infer(env, e[2]); unify(a, infer(env, e[3])); return a
    if k == 'anno':
        unify(infer(env, e[1]), e[2]); return e[2]
    if k == 'let':
        t = infer(env, e[3])
        if e[2] is not None: unify(t, e[2]); t = e[2]
        return infer((e[1], t, env), e[4])
    if k == 'letrec':
        env2 = (e[1], e[2], env)
        unify(infer(env2, e[3]), e[2])
        return infer(env2, e[4])
    raise TErr()

# compile to closures-free evaluation with tail-loop
def lookup(env, x):
    while True:
        if env[0] == x: return env[1]
        env = env[2]

class Clo:
    __slots__ = ('x', 'body', 'env')
    def __init__(self, x, body, env): self.x = x; self.body = body; self.env = env

def ev(e, env):
    while True:
        k = e[0]
        if k == 'var':
            x = e[1]
            while env[0] != x: env = env[2]
            return env[1]
        if k == 'int' or k == 'bool': return e[1]
        if k == 'bin':
            a = ev(e[2], env); b = ev(e[3], env); op = e[1]
            if op == '+': return a + b
            if op == '-': return a - b
            if op == '*': return a * b
            if op == '<': return a < b
            if op == '==': return a == b
            if b == 0: raise RErr()
            if op == '//': return a // b
            return a % b
        if k == 'app':
            f = ev(e[1], env); v = ev(e[2], env)
            env = (f.x, v, f.env); e = f.body; continue
        if k == 'lam': return Clo(e[1], e[2], env)
        if k == 'if':
            e = e[2] if ev(e[1], env) else e[3]; continue
        if k == 'let':
            env = (e[1], ev(e[3], env), env); e = e[4]; continue
        if k == 'anno': e = e[1]; continue
        if k == 'letrec':
            lam = e[3]
            c = Clo(lam[1], lam[2], None)
            env = [e[1], c, env]
            c.env = env
            e = e[4]; continue

def main():
    out = None; code = 1
    try:
        data = open(sys.argv[2], 'rb').read()
        try:
            s = data.decode('ascii')
        except Exception:
            raise PErr()
        prog = Parser(lex(s)).program()
        infer(None, prog)
        v = ev(prog, None)
        if isinstance(v, bool): out = 'True' if v else 'False'
        elif isinstance(v, int): out = str(v)
        else: out = '<function>'
        code = 0
    except PErr: out = 'ParseError'
    except TErr: out = 'TypeError'
    except RErr: out = 'RuntimeError'
    except RecursionError: out = 'RuntimeError: recursion'
    sys.stdout.write(out + '\n'); sys.stdout.flush()
    res[0] = code

res = [1]
if __name__ == '__main__':
    sys.set_int_max_str_digits(0)
    sys.setrecursionlimit(10**7)
    threading.stack_size(1 << 30)
    t = threading.Thread(target=main); t.start(); t.join()
    sys.exit(res[0])
